## Test File

### test/System.invariant.t.sol

A comprehensive invariant test harness for the Auction contract, designed to work with **both Foundry fuzzing and Halmos symbolic execution**.

- **License:** GPL-3.0 or above, Solidity `^0.8.24`
- **Inherits:** `Test` (forge-std), `SymTest` (halmos-cheatcodes)
- **Ghost state variables:** `ghost_bidSum`, `ghost_max_bidder`, `ghost_nbid`, `ghost_winner`, `ghost_has_finished`, `ghost_n_iterations`, `ghost_bids` mapping
- **3 bidders** created in `setUp()` with 100,000 ERC20 tokens each
- **Two action structs:** `Action` (for Foundry fuzzing with `bidderSeed`) and `ActionHalmos` (for Halmos with `bidderIndex`)
- **Action types enum:** `BID`, `FINISH`, `NOOP`

**Two entry points:**
1. **`check_SystemInvariants(ActionHalmos[3] memory actions)`** -- Halmos entry point (matches `function = "check"` in halmos.toml). Uses `vm.assume()` for constraints.
2. **`test_SystemInvariants(Action[4] memory actions)`** -- Foundry fuzzing entry point. Uses `bound()` for constraints.

**Bug note:** Lines 121-123 in `test_SystemInvariants` all bound `actions[0].actionType` instead of `actions[1]`, `actions[2]`, `actions[3]` respectively.

**Invariant assertions (`_assertInvariants`):**
- If auction finished and there were bids: winner must be non-zero address, max bidder must equal winner, winner must own the completed NFT.

**Key observation:** The `Auction.bid()` and `Auction.finishAuction()` functions have **empty bodies**, so the test will likely fail or behave unexpectedly until those are implemented.

Full content:

```solidity
// SPDX-License-Identifier: GPL-3.0 or above
pragma solidity ^0.8.24;

import {Test} from "forge-std/Test.sol";
import {Auction} from "../src/Auction.sol";
import {ZPunks} from "../src/impls/RealNFT.sol";
import {ERC20Mock} from "@openzeppelin/contracts/mocks/token/ERC20Mock.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import {SymTest} from "halmos-cheatcodes/SymTest.sol";

contract SystemInvariantTest is Test, SymTest {
    Auction public auction;
    ZPunks public nft;
    ERC20Mock public token;

    uint256 public ghost_bidSum;
    address public ghost_max_bidder;
    uint256 public ghost_nbid;
    address public ghost_winner;
    bool public ghost_has_finished;
    uint256 public ghost_n_iterations;

    address[] public bidders;
    address public owner;

    mapping(address => uint256) public ghost_bids;

    enum ActionType {
        BID,
        FINISH,
        NOOP
    }

    struct Action {
        uint8 actionType;
        uint256 amount;
        uint256 bidderSeed;
    }

    struct ActionHalmos {
        uint8 actionType;
        uint256 amount;
        uint8 bidderIndex;
    }

    function setUp() public {
        token = new ERC20Mock();
        ghost_nbid = 0;
        ghost_n_iterations = 0;
        ghost_has_finished = false;

        for (uint256 i = 0; i < 3; i++) {
            address bidder = makeAddr(string(abi.encodePacked("bidder", i)));
            bidders.push(bidder);
            token.mint(bidder, 100_000);
        }

        owner = makeAddr("owner");
        nft = new ZPunks(owner);

        instantiate_auction();
    }

    function instantiate_auction() internal {
        vm.startPrank(owner);
        nft.safeMint(owner, "");

        auction = new Auction(
            IERC20(address(token)),
            IERC721(address(nft)),
            ghost_n_iterations,
            owner,
            block.timestamp,
            block.timestamp + 7 days
        );

        nft.approve(address(auction), ghost_n_iterations);
        vm.stopPrank();
    }

    function check_SystemInvariants(ActionHalmos[3] memory actions) public {
        vm.assume(actions[0].actionType <= 2 && actions[0].bidderIndex <= 2);
        vm.assume(actions[1].actionType <= 2 && actions[1].bidderIndex <= 2);
        vm.assume(actions[2].actionType <= 2 && actions[2].bidderIndex <= 2);

        vm.assume(actions[0].amount >= 1 && actions[0].amount <= 100_000);
        vm.assume(actions[1].amount >= 1 && actions[1].amount <= 100_000);
        vm.assume(actions[2].amount >= 1 && actions[2].amount <= 100_000);

        for (uint256 i = 0; i < actions.length; i++) {
            ActionHalmos memory action = actions[i];
            ActionType act = ActionType(action.actionType);
            address currentBidder = bidders[action.bidderIndex];

            if (act == ActionType.BID) {
                _executeBid(currentBidder, action.amount);
            } else if (act == ActionType.FINISH) {
                _executeFinish(currentBidder);
            }

            _assertInvariants();
        }
        _executeFinish(owner);
    }

    function test_SystemInvariants(Action[4] memory actions) public {
        actions[0].actionType = uint8(bound(actions[0].actionType, 0, 2));
        actions[1].actionType = uint8(bound(actions[0].actionType, 0, 2));
        actions[2].actionType = uint8(bound(actions[0].actionType, 0, 2));
        actions[3].actionType = uint8(bound(actions[0].actionType, 0, 2));

        for (uint256 i = 0; i < actions.length; i++) {
            Action memory action = actions[i];
            ActionType act = ActionType(action.actionType);

            uint256 bidderIndex = action.bidderSeed % bidders.length;
            address currentBidder = bidders[bidderIndex];

            if (act == ActionType.BID) {
                uint256 boundedAmount = bound(action.amount, 1, 100_000);
                _test_executeBid(currentBidder, boundedAmount);
            } else if (act == ActionType.FINISH) {
                _test_executeFinish(currentBidder);
            }

            _assertInvariants();
        }
        _test_executeFinish(owner);
        instantiate_auction();
    }

    function _executeBid(address bidder, uint256 amount) internal {
        vm.startPrank(bidder);
        token.approve(address(auction), amount);

        if (ghost_has_finished) {
            vm.stopPrank();
            return;
        }
        auction.bid(amount);
        ghost_nbid += 1;
        ghost_bids[bidder] += amount;
        ghost_bidSum += amount;

        if (ghost_max_bidder == address(0) || ghost_bids[bidder] > ghost_bids[ghost_max_bidder]) {
            ghost_max_bidder = bidder;
        }

        vm.stopPrank();
    }

    function _executeFinish(address caller) internal {
        vm.warp(block.timestamp + 7 days + 1);

        vm.startPrank(caller);
        if (ghost_has_finished) {
            vm.stopPrank();
