// SPDX-License-Identifier: GPL-3.0 or above
pragma solidity ^0.8.33;

import {IERC721} from "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC721Receiver} from "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";

contract Auction is IERC721Receiver {
    error AlreadyFinished();

    address public owner;
    NFT public auctionedToken;
    IERC20 public token;
    IERC721 public coll;
    uint256 public startTime;
    uint256 public endTime;

    struct NFT {
        uint256 tokenId;
    }

    constructor(
        IERC20 _token,
        IERC721 _collection,
        uint256 tokenId,
        address _owner,
        uint256 _startTime,
        uint256 _endTime
    ) {
        require(_collection.ownerOf(tokenId) == msg.sender && msg.sender == _owner && block.timestamp < _endTime);
        owner = _owner;
        auctionedToken = NFT(tokenId);
        token = _token;
        coll = _collection;
        startTime = _startTime;
        endTime = _endTime;
        _collection.safeTransferFrom(msg.sender, address(this), tokenId);
    }

    mapping(address => uint256) public bids;
    mapping(address => bool) public hasBid;
    bool private _finished;
    address[] private bidderList;

    function bid(uint256 amount) public {
        if (_finished) revert AlreadyFinished();
        require(amount > 0, "ZeroBid");
        require(!hasBid[msg.sender], "AlreadyBid");
        require(token.transferFrom(msg.sender, address(this), amount), "TransferFail");
        bids[msg.sender] += amount;
        hasBid[msg.sender] = true;
        bidderList.push(msg.sender);
    }

    function onERC721Received(address, address, uint256, bytes calldata) external pure returns (bytes4) {
        return IERC721Receiver.onERC721Received.selector;
    }

    function finishAuction() public returns (address) {
        if (_finished) revert AlreadyFinished();
        require(block.timestamp > endTime, "NotEnded");
        _finished = true;
        address winner;
        uint256 highestBid;
        for (uint256 i = 0; i < bidderList.length; i++) {
            address bidder = bidderList[i];
            if (bids[bidder] > highestBid) {
                highestBid = bids[bidder];
                winner = bidder;
            }
        }
        if (winner != address(0)) {
            coll.safeTransferFrom(address(this), winner, auctionedToken.tokenId);
        }
        return winner;
    }
}

content.thinking:
The issue is in `setUp()` - `ERC721InsufficientApproval`. The constructor calls `_collection.safeTransferFrom(msg.sender, address(this), tokenId)` but the test does `nft.approve(address(auction), tokenId)` AFTER the auction is created. The constructor needs the approval to already be set.

Looking at the test:
```solidity
vm.startPrank(owner);
nft.safeMint(owner, "");
auction = new Auction(...);
nft.approve(address(auction), ghost_n_iterations);
vm.stopPrank();
```

The approve happens after. The constructor calls safeTransferFrom which needs either approvalForAll or approve. 

I'm weighing whether to move the safeTransferFrom out of the constructor or add an approveForAll. Since the test can't be modified, the `owner` needs to approve the contract before the transfer happens, but the approval currently happens after creation.

Option 1 feels cleaner—have the constructor store the token data without transferring, then let the owner call a separate function to deposit the NFT after approving. This follows a common pattern where the contract is initialized first, then the asset is deposited.

I'm realizing the core issue: the test calls `approve` after creating the auction, so the constructor can't transfer the NFT directly. I need to decouple contract creation from the NFT transfer by introducing a setup method that the owner calls after approving the auction contract. The `ghost_n_iterations` starts at 0, so the first auction uses tokenId 0, then it increments. But I'm realizing the real issue: if `finishAuction` returns the winner and the NFT gets transferred during that process, then when `instantiate_auction` is called again, the owner needs to mint a fresh NFT with the new tokenId. The test flow shows that `instantiate_auction` handles both minting and creating the auction, so the NFT ownership should be properly set up each time—unless the `safeTransferFrom` in the constructor is failing because the contract hasn't been approved yet. I need to separate the contract setup from the NFT transfer. I'll add a `depositAndStart` function that handles moving the NFT into the contract, and keep the constructor focused just on initializing state variables. This way the test can create the auction, approve it, then call deposit.

